package com.flashlearn.data.backup

import com.flashlearn.database.RoomFlashLearnDatabase
import com.flashlearn.domain.backup.BackupType
import org.json.JSONArray
import org.json.JSONObject
import javax.inject.Inject
import javax.inject.Singleton

@Singleton
class TypedBackupRepository @Inject constructor(private val db:RoomFlashLearnDatabase){
 suspend fun export(type:BackupType):String{val root=JSONObject().put("schemaVersion",2).put("exportedAt",java.time.Instant.now().toString()).put("backupType",type.name);when(type){BackupType.VOCABULARY->{root.put("concepts",JSONArray(db.conceptDao().getAll().map{JSONObject().put("id",it.id.toString()).put("entryType",it.entryType).put("categoryId",it.categoryId?.toString()).put("favorite",it.favorite).put("active",it.active).put("createdAt",it.createdAt.toString()).put("updatedAt",it.updatedAt.toString())}));root.put("contents",JSONArray(db.contentDao().getAll().map{JSONObject().put("id",it.id.toString()).put("conceptId",it.conceptId.toString()).put("languageCode",it.languageCode).put("text",it.text).put("canonicalKey",it.canonicalKey).put("notes",it.notes).put("grammarNote",it.grammarNote).put("possibleCorrection",it.possibleCorrection).put("translationIndex",it.translationIndex).put("pronunciation",it.pronunciation).put("example",it.example)}));root.put("tags",JSONArray(db.tagDao().getAll().map{JSONObject().put("id",it.id.toString()).put("name",it.name)}));root.put("categories",JSONArray(db.categoryDao().getAll().map{JSONObject().put("id",it.id.toString()).put("name",it.name)}));root.put("relations",JSONArray(db.vocabularyRelationDao().getAll().map{JSONObject().put("id",it.id.toString()).put("sourceConceptId",it.sourceConceptId.toString()).put("targetConceptId",it.targetConceptId?.toString()).put("relationType",it.relationType).put("unresolvedText",it.unresolvedText)}));root.put("variants",JSONArray(db.vocabularyVariantDao().getAll().map{JSONObject().put("id",it.id.toString()).put("conceptId",it.conceptId.toString()).put("text",it.text).put("variantType",it.variantType)}));root.put("languages",JSONArray(db.languageDao().getAll().map{JSONObject().put("code",it.code).put("name",it.name).put("active",it.active)}));root.put("languagePairs",JSONArray(db.languagePairDao().getAll().map{JSONObject().put("sourceLanguageCode",it.sourceLanguageCode).put("targetLanguageCode",it.targetLanguageCode).put("active",it.active)}))};BackupType.PROGRESS->{root.put("learningStates",JSONArray(db.learningStateDao().getAll().map{JSONObject().put("id",it.id.toString()).put("conceptId",it.conceptId.toString()).put("stage",it.stage).put("nextReviewAt",it.nextReviewAt?.toString()).put("monthlyWrongCount",it.monthlyWrongCount).put("hasPathFailure",it.hasPathFailure).put("totalCorrect",it.totalCorrect).put("totalWrong",it.totalWrong).put("lastReviewedAt",it.lastReviewedAt?.toString())}));root.put("difficultyStates",JSONArray(db.difficultyStateDao().getAll().map{JSONObject().put("id",it.id.toString()).put("conceptId",it.conceptId.toString()).put("current",it.current).put("consecutiveCorrect",it.consecutiveCorrect).put("consecutiveWrong",it.consecutiveWrong).put("hasReachedVeryHard",it.hasReachedVeryHard)}));root.put("reviewSessions",JSONArray(db.reviewSessionDao().getAll().map{JSONObject().put("id",it.id.toString()).put("startedAt",it.startedAt.toString()).put("endedAt",it.endedAt?.toString()).put("reviewType",it.reviewType)}));root.put("reviewHistory",JSONArray(db.reviewHistoryDao().getAll().map{JSONObject().put("id",it.id.toString()).put("sessionId",it.sessionId.toString()).put("reviewAttemptId",it.reviewAttemptId.toString()).put("conceptId",it.conceptId.toString()).put("reviewedAt",it.reviewedAt.toString()).put("isCorrect",it.isCorrect).put("reviewType",it.reviewType)}))};BackupType.FULL->{return export(BackupType.VOCABULARY).let{v->JSONObject(v).apply{val p=JSONObject(export(BackupType.PROGRESS));p.keys().forEach{key->if(key!="schemaVersion"&&key!="exportedAt"&&key!="backupType")put(key,p.get(key))};put("backupType","FULL")}.toString()}}};return root.toString()}
}
